namespace StarlightSyndicateDemo;
internal static class FittingTextFormat
{
 internal static string Export(FittingDesign d){var lines=new List<string>{$"[{d.Ship.HullName}, {d.Name}]"};foreach(var bank in new[]{"low","medium","high","rig"}){foreach(var m in FittingLayoutModel.Installed(d.Ship).Where(m=>m.Bank==bank))lines.Add(m.Name+(m.Payload.Length>0?", "+DemoWorld.ItemName(m.Payload):""));lines.Add("");}foreach(var u in d.Ship.Drones.Where(u=>u.Owner=="player"&&u.Location is "Bay" or "Reserve").GroupBy(u=>u.TypeId))lines.Add(DemoWorld.ItemName(u.Key)+" x"+u.Sum(u=>u.Count));return string.Join(Environment.NewLine,lines);}
 internal static FittingDesign Import(string text){var lines=text.Split('\n').Select(s=>s.Trim()).Where(s=>s.Length>0).ToArray();if(lines.Length==0||!lines[0].StartsWith('[')||!lines[0].EndsWith(']'))throw new InvalidDataException("Expected [Hull name, Fitting name] header");var head=lines[0][1..^1].Split(',',2);var hull=FleetCatalog.All.FirstOrDefault(h=>h.Name.Equals(head[0].Trim(),StringComparison.OrdinalIgnoreCase)||h.SourceHull.Equals(head[0].Trim(),StringComparison.OrdinalIgnoreCase)||h.Id==head[0].Trim())??throw new InvalidDataException("Unknown fitting hull");var ship=new Ship();ship.ApplyFleetHull(hull,true);var sim=new FittingSimulation(ship);FittingSimulation.ClearEquipment(sim.World.Player);
 string Find(string name)=>ItemCatalog.All.FirstOrDefault(i=>i.Name.Equals(name.Trim(),StringComparison.OrdinalIgnoreCase)||i.Id==name.Trim())?.Id??throw new InvalidDataException("Unknown fitting item: "+name);
 foreach(var line in lines.Skip(1)){if(line.StartsWith('['))continue;var parts=line.Split(',',2);string item=parts[0];int count=1;int at=item.LastIndexOf(" x",StringComparison.OrdinalIgnoreCase);if(at>0&&int.TryParse(item[(at+2)..],out int n)){count=n;item=item[..at];}if(count<1||count>1000)throw new InvalidDataException("Invalid fitting quantity");string id=Find(item);if(DroneCatalog.ById.TryGetValue(id,out var drone)){if(!sim.World.LoadDrone(id,true,count))throw new InvalidDataException("Drone bay does not accept "+item);continue;}if(!FittingLayoutModel.ById.TryGetValue(id,out var spec))throw new InvalidDataException("Only modules, rigs and drones belong in a fitting body");for(int i=0;i<count;i++){int slot=FittingLayoutModel.Destination(sim.World.Player,spec);if(slot<0||!sim.Fit(spec,slot))throw new InvalidDataException("Incompatible module: "+item);if(parts.Length>1){string charge=Find(parts[1]);bool loaded=spec.Kind switch{"weapon"=>sim.World.LoadWeapon(slot,charge),"ewar"=>sim.World.LoadEwarPayload(slot,charge),"defense"=>sim.World.LoadDefensePayload(slot,charge),"support"=>sim.World.LoadSupportPayload(slot,charge),"enhancement"=>sim.World.LoadEnhancementScript(slot,charge),"utility"=>sim.World.LoadUtilityPayload(slot,charge,true),_=>false};if(!loaded)throw new InvalidDataException("Incompatible charge: "+parts[1]);}}}
 return FittingDesign.Capture(sim.World.Player,head.Length>1?head[1].Trim():hull.Name+" fit");}
}
public sealed partial class DemoWorld
{
 internal bool UnloadFittingPayload(FittingModule m){if(m.Active||!Docked)return false;switch(m.Kind){case "weapon":var w=Player.WeaponAt(m.Index);if(w==null||w.ReloadLeft>0)return false;ReturnMagazine(w,true);w.ChargeId="";return true;case "ewar":ReturnEwarPayload(Player.Ewar[m.Index]);Player.Ewar[m.Index].PayloadId="";return true;case "defense":return LoadDefensePayload(m.Index,"");case "support":return LoadSupportPayload(m.Index,"");case "enhancement":return LoadEnhancementScript(m.Index,"");case "utility":Player.Utilities[m.Index].ReloadLeft=0;return LoadUtilityPayload(m.Index,"",true);default:return false;}}
}
